import{_ as e,o as a,c as l,a0 as s}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"Number.MAX_SAFE_INTEGER","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Number/MAX_SAFE_INTEGER.md","filePath":"jsApi/Number/MAX_SAFE_INTEGER.md","lastUpdated":1791573371000}'),r={name:"jsApi/Number/MAX_SAFE_INTEGER.md"};function n(i,t,o,p,d,E){return a(),l("div",null,[...t[0]||(t[0]=[s(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Number/MAX_SAFE_INTEGER" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/MAX_SAFE_INTEGER" target="_blank">en</a></p><h1 id="number-max-safe-integer" tabindex="-1">Number.MAX_SAFE_INTEGER <a class="header-anchor" href="#number-max-safe-integer" aria-label="Permalink to &quot;Number.MAX_SAFE_INTEGER&quot;">​</a></h1><p>Number.MAX_SAFE_INTEGER 常量表示在 JavaScript 中最大的安全整数（maxinum safe integer)（253 - 1）。</p><p>Number.MAX_SAFE_INTEGER 属性的属性特性：</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;">writable</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">enumerable</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">configurable</td><td style="text-align:left;">false</td></tr></tbody></table><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>MAX_SAFE_INTEGER 常量值为 9007199254740991。这个数字形成的原因是，Javascript 使用 IEEE 754 中规定的 double-precision floating-point format numbers，在这个规定中能安全的表示数字的范围在 -(253 - 1) 到 253 - 1 之间，包含 -(253 - 1) 和 253 - 1。</p><p>安全（Safe）在本文中的提到的意思是指能够准确地表示整数和正确地比较整数。例如 Number.MAX_SAFE_INTEGER + 1 === Number.MAX_SAFE_INTEGER + 2 将返回 true。这在数学上并不正确。参见Number.isSafeInteger()获取更多信息.</p><p>由于 MAX_SAFE_INTEGER 是Number的一个静态属性，所以你可以直接使用Number.MAX_SAFE_INTEGER，而不用自己创建一个Number对象的属性。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Number.MAX_SAFE_INTEGER </span><span style="color:#6A737D;">// 9007199254740991</span></span>
<span class="line"><span style="color:#24292E;">Math.</span><span style="color:#6F42C1;">pow</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">53</span><span style="color:#24292E;">) </span><span style="color:#D73A49;">-</span><span style="color:#005CC5;"> 1</span><span style="color:#6A737D;">     // 9007199254740991</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr></tbody></table>`,13)])])}const _=e(r,[["render",n]]);export{b as __pageData,_ as default};
